package yq

import (
	"fmt"
	"strings"
)

// Kind classifies a node in the data tree.
type Kind uint32

const (
	DocumentNode Kind = 1 << iota
	SequenceNode
	MappingNode
	ScalarNode
	AliasNode
)

func (k Kind) String() string {
	switch k {
	case DocumentNode:
		return "document"
	case SequenceNode:
		return "sequence"
	case MappingNode:
		return "map"
	case ScalarNode:
		return "scalar"
	case AliasNode:
		return "alias"
	}
	return "unknown"
}

// Style records how a node was (or should be) rendered.
type Style uint32

const (
	TaggedStyle Style = 1 << iota
	DoubleQuotedStyle
	SingleQuotedStyle
	LiteralStyle
	FoldedStyle
	FlowStyle
)

// Common YAML tags.
const (
	tagStr       = "!!str"
	tagInt       = "!!int"
	tagFloat     = "!!float"
	tagBool      = "!!bool"
	tagNull      = "!!null"
	tagMap       = "!!map"
	tagSeq       = "!!seq"
	tagTimestamp = "!!timestamp"
	tagMerge     = "!!merge"
	tagBinary    = "!!binary"
)

// Node is the universal data node used throughout the processor.
type Node struct {
	Kind  Kind
	Style Style
	Tag   string
	Value string

	Anchor  string
	Alias   *Node
	Content []*Node

	HeadComment string
	LineComment string
	FootComment string

	Parent *Node
	Key    *Node

	// LeadingContent holds raw text (header comments, separators) that must be
	// reproduced verbatim ahead of this node.
	LeadingContent  string
	TrailingContent string

	Line   int
	Column int

	document  int
	filename  string
	fileIndex int

	IsMapKey         bool
	EvaluateTogether bool
}

func newNode(kind Kind, tag, value string) *Node {
	return &Node{Kind: kind, Tag: tag, Value: value}
}

func scalarNode(tag, value string) *Node {
	return &Node{Kind: ScalarNode, Tag: tag, Value: value}
}

func stringNode(v string) *Node   { return scalarNode(tagStr, v) }
func boolNode(v bool) *Node       { return scalarNode(tagBool, boolStr(v)) }
func nullNode() *Node             { return scalarNode(tagNull, "null") }
func intNode(v int) *Node         { return scalarNode(tagInt, fmt.Sprintf("%v", v)) }
func int64Node(v int64) *Node     { return scalarNode(tagInt, fmt.Sprintf("%v", v)) }
func floatNode(v float64) *Node   { return scalarNode(tagFloat, formatFloat(v)) }
func emptyMap() *Node             { return &Node{Kind: MappingNode, Tag: tagMap} }
func emptySeq() *Node             { return &Node{Kind: SequenceNode, Tag: tagSeq} }

func boolStr(v bool) string {
	if v {
		return "true"
	}
	return "false"
}

// Copy makes a deep copy of the node, detached from its parent.
func (n *Node) Copy() *Node {
	if n == nil {
		return nil
	}
	c := n.copyInto(nil)
	return c
}

func (n *Node) copyInto(parent *Node) *Node {
	c := &Node{}
	*c = *n
	c.Parent = parent
	c.Content = nil
	if len(n.Content) > 0 {
		c.Content = make([]*Node, len(n.Content))
		for i, child := range n.Content {
			c.Content[i] = child.copyInto(c)
		}
	}
	if n.Key != nil {
		c.Key = n.Key.Copy()
	}
	return c
}

// CopyAsChild returns a deep copy suitable for insertion under parent.
func (n *Node) CopyAsChild() *Node { return n.Copy() }

// SetValueFrom replaces the data-carrying parts of n with those of other,
// keeping identity (parent/key) intact.
func (n *Node) SetValueFrom(other *Node) {
	parent, key, isKey := n.Parent, n.Key, n.IsMapKey
	head, foot := n.HeadComment, n.FootComment
	*n = *other
	n.Parent = parent
	n.Key = key
	n.IsMapKey = isKey
	if n.HeadComment == "" {
		n.HeadComment = head
	}
	if n.FootComment == "" {
		n.FootComment = foot
	}
	for _, c := range n.Content {
		c.Parent = n
	}
}

// UpdateFrom replaces content while preserving comments/anchors as yq does.
func (n *Node) UpdateFrom(other *Node, prefs assignPrefs) {
	cp := other.Copy()
	if prefs.ClobberCustomTags || n.Tag == "" || strings.HasPrefix(n.Tag, "!!") || cp.Tag != "" {
		n.Tag = cp.Tag
	}
	n.Kind = cp.Kind
	n.Style = cp.Style
	n.Value = cp.Value
	n.Content = cp.Content
	n.Alias = cp.Alias
	if cp.Anchor != "" {
		n.Anchor = cp.Anchor
	}
	if cp.LineComment != "" {
		n.LineComment = cp.LineComment
	}
	for _, c := range n.Content {
		c.Parent = n
	}
}

type assignPrefs struct {
	ClobberCustomTags bool
}

// isMapping etc. convenience.
func (n *Node) isCollection() bool {
	return n.Kind == MappingNode || n.Kind == SequenceNode
}

func (n *Node) isNull() bool {
	return n.Kind == ScalarNode && (n.Tag == tagNull || n.Tag == "!!null")
}

// GetKeyValue looks up a key in a mapping node, returning the value node.
func (n *Node) mapGet(key string) (*Node, *Node) {
	if n.Kind != MappingNode {
		return nil, nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i], n.Content[i+1]
		}
	}
	return nil, nil
}

func (n *Node) mapSet(key string, value *Node) {
	k, _ := n.mapGet(key)
	if k != nil {
		for i := 0; i+1 < len(n.Content); i += 2 {
			if n.Content[i] == k {
				value.Parent = n
				value.Key = k
				n.Content[i+1] = value
				return
			}
		}
	}
	kn := stringNode(key)
	kn.Parent = n
	kn.IsMapKey = true
	value.Parent = n
	value.Key = kn
	n.Content = append(n.Content, kn, value)
}

func (n *Node) addChild(c *Node) {
	c.Parent = n
	n.Content = append(n.Content, c)
}

// Path computes the path of this node from the document root.
func (n *Node) Path() []interface{} {
	if n == nil {
		return nil
	}
	if n.Parent == nil {
		return []interface{}{}
	}
	parentPath := n.Parent.Path()
	if n.Parent.Kind == MappingNode {
		if n.Key != nil {
			return append(parentPath, n.Key.Value)
		}
		return parentPath
	}
	if n.Parent.Kind == SequenceNode {
		for i, c := range n.Parent.Content {
			if c == n {
				return append(parentPath, i)
			}
		}
	}
	return parentPath
}

func (n *Node) pathNode() *Node {
	seq := emptySeq()
	for _, p := range n.Path() {
		switch v := p.(type) {
		case string:
			seq.addChild(stringNode(v))
		case int:
			seq.addChild(intNode(v))
		}
	}
	return seq
}

// GetNiceTag returns the tag, resolving empty tags.
func (n *Node) guessTag() string {
	if n.Tag != "" {
		return n.Tag
	}
	switch n.Kind {
	case MappingNode:
		return tagMap
	case SequenceNode:
		return tagSeq
	case AliasNode:
		return "!!alias"
	}
	return tagStr
}
